test('存草稿同步云端携带现场照片附件字段（save() draft 带 photos）', async () => {
  vi.stubEnv('VITE_API_BASE_URL', '/api')
  const request = vi.spyOn(requestModule, 'request').mockResolvedValue('inspection-draft')
  const store = createFloodStore(storage)()
  // 模拟 index.vue:261 save() 构造的 draft（已补 photos 字段）
  const draft = {
    eventId: 'event-1', complexId: 'complex-1', items: [{ templateItemId: 'item-1', label: '项', fillType: '1', value: '正常' }],
    photos: [{ id: 'p1', source: '', url: '/file/draft.jpg', status: 'done', name: 'draft.jpg' }],
  }
  const res = await store.syncDraftToCloud('pre', draft)
  expect(res.synced).toBe(true)
  const saveCall = request.mock.calls.find(c => String(c[0]).includes('/inspection/save'))
  expect(saveCall?.[1]).toEqual(expect.objectContaining({
    data: expect.objectContaining({
      inspectionFileUrl: '/file/draft.jpg',
      inspectionFileName: 'draft.jpg',
    }),
  }))
})

